         slot: Tracked<FlatCombiner::slots>,
         flat_combiner_instance: Tracked<FlatCombiner::Instance>,
         unbounded_log_instance: Tracked<UnboundedLog::Instance<DT>>,
     ) -> (res: (Context<DT>, Tracked<PointsTo<PendingOperation<DT>>>))
