9000. pub mod flat_combiner {
9001. // ===== BEGIN INLINED DEPENDENCY: src/spec/flat_combiner.rs =====
9002. // Verified Node Replication Library
9003. // SPDX-License-Identifier: Apache-2.0 OR MIT
9004. //
9005. #[allow(unused_imports)]
9006. use verus_builtin::*;
9007. use verus_builtin_macros::*;
9008. 
9009. use vstd::prelude::*;
9010. 
9011. use verus_state_machines_macros::*;
9012. 
9013. use super::types::*;
9014. // use super::utils::*;
9015. 
9016. verus! {
9017. 
9018. /// represents the state of a client thread
9019. #[is_variant]
9020. pub tracked enum ClientState {
9021.     Idle,
9022.     Waiting(ReqId),
9023. }
9024. 
9025. /// represents the state of a request in the queue
9026. #[is_variant]
9027. pub tracked enum SlotState {
9028.     Empty,
9029.     Request(ReqId),
9030.     InProgress(ReqId),
9031.     Response(ReqId),
9032. }
9033. 
9034. impl SlotState {
9035.     pub open spec fn get_ReqId(&self) -> ReqId {
9036.         match self {
9037.             SlotState::Empty => arbitrary(),
9038.             SlotState::Request(reqid) => *reqid,
9039.             SlotState::InProgress(reqid) => *reqid,
9040.             SlotState::Response(reqid) => *reqid,
9041.         }
9042.     }
9043. }
9044. 
9045. /// represents the combiner state
9046. #[is_variant]
9047. pub tracked enum CombinerState {
9048.     Collecting(Seq<Option<ReqId>>),
9049.     Responding(Seq<Option<ReqId>>, nat),
9050. }
9051. 
9052. impl CombinerState {
9053.     pub open spec fn req_len(self) -> nat {
9054.         match self {
9055.             CombinerState::Collecting(reqs) => reqs.len(),
9056.             CombinerState::Responding(reqs, _) => reqs.len(),
9057.         }
9058.     }
9059. 
9060.     pub open spec fn req_is_none(self, tid: nat) -> bool
9061.         recommends
9062.             0 <= tid < self.req_len(),
9063.     {
9064.         match self {
9065.             CombinerState::Collecting(reqs) => reqs[tid as int].is_none(),
9066.             CombinerState::Responding(reqs, _) => reqs[tid as int].is_none(),
9067.         }
9068.     }
9069. 
9070.     pub open spec fn req_is_some(self, tid: nat) -> bool
9071.         recommends
9072.             0 <= tid < self.req_len(),
9073.     {
9074.         match self {
9075.             CombinerState::Collecting(reqs) => reqs[tid as int].is_some(),
9076.             CombinerState::Responding(reqs, _) => reqs[tid as int].is_some(),
9077.         }
9078.     }
9079. }
9080. 
9081. // The flat combiner state machine
9082. tokenized_state_machine! {
9083. FlatCombiner {
9084.     fields {
9085.         /// the number of threads
9086.         #[sharding(constant)]
9087.         pub num_threads: nat,
9088. 
9089.         /// clients of the replica
9090.         #[sharding(map)]
9091.         pub clients: Map<ThreadId, ClientState>,
9092. 
9093.         #[sharding(map)]
9094.         pub slots: Map<ThreadId, SlotState>,
9095. 
9096.         #[sharding(variable)]
9097.         pub combiner: CombinerState,
9098.     }
9099. 
9100.     ////////////////////////////////////////////////////////////////////////////////////////////
9101.     // Invariant
9102.     ////////////////////////////////////////////////////////////////////////////////////////////
9103. 
9104.     #[invariant]
9105.     pub fn inv_complete(&self) -> bool {
9106.         // clients are complete
9107.         &&& (forall |i| self.clients.contains_key(i) <==> i < self.num_threads)
9108.         // slots are complete
9109.         &&& (forall |i| self.slots.contains_key(i) <==> i < self.num_threads)
9110.     }
9111. 
9112. 
9113.     // && Complete(x)
9114.     #[invariant]
9115.     pub fn inv_client_slot_empty(&self) -> bool {
9116.         forall |i:nat| #[trigger] self.clients.contains_key(i)
9117.             ==>  (self.clients[i].is_Idle() <==> self.slots[i].is_Empty())
9118.     }
9119. 
9120.     #[invariant]
9121.     pub fn inv_client_reqids(&self) -> bool {
9122.         forall |i:nat| #[trigger] self.clients.contains_key(i) && self.clients[i].is_Waiting()
9123.             ==> self.clients[i].get_Waiting_0() == self.slots[i].get_ReqId()
9124.     }
9125. 
9126.     #[invariant]
9127.     pub fn inv_combiner_elements(&self) -> bool {
9128.         match self.combiner {
9129.             CombinerState::Collecting(elems) => {
9130.                 elems.len() <= self.num_threads
9131.             },
9132.             CombinerState::Responding(elems, idx) => {
9133.                 &&& elems.len() == self.num_threads
9134.                 &&& idx <= elems.len()
9135.             },
9136.         }
9137.     }
9138. 
9139.     pub open spec fn slot_in_progress(slots: Map<nat, SlotState>, tid: nat) -> bool
9140.         recommends slots.contains_key(tid)
9141.     {
9142.         slots[tid].is_InProgress()
9143.     }
9144. 
9145.     #[invariant]
9146.     pub fn inv_combiner_slots_not_in_progress(&self) -> bool {
9147.         match self.combiner {
9148.             CombinerState::Collecting(elems) => {
9149.                 // fff
9150.                 &&& (forall |i: nat| 0 <= i < elems.len() && elems[i as int].is_none()
9151.                     ==> !(#[trigger] self.slots[i]).is_InProgress()) //Self::slot_in_progress(self.slots, i)))
9152.                 // everything above is not in progress
9153.                 &&& (forall |i: nat| elems.len() <= i < self.num_threads ==> !self.slots[i].is_InProgress())
9154.             },
9155.             CombinerState::Responding(elems, idx) => {
9156.                 &&& (forall |i: nat| 0 <= i < elems.len() && elems[i as int].is_none()
9157.                     ==> !(#[trigger] self.slots[i]).is_InProgress()) //Self::slot_in_progress(self.slots, i)))
9158.                 &&& (forall |i: nat| 0 <= i < idx ==> !self.slots[i].is_InProgress())
9159.             },
9160.         }
9161.     }
9162. 
9163.     #[invariant]
9164.     pub fn inv_combiner_request_ids(&self) -> bool {
9165.         match self.combiner {
9166.             CombinerState::Collecting(elems) => {
9167.                 forall |i:nat| (0 <= i < elems.len() && elems[i as int].is_some())
9168.                     ==> (#[trigger] self.slots[i]).is_InProgress() && (#[trigger] self.slots[i]).get_InProgress_0() == elems[i as int].unwrap()
9169.             },
9170.             CombinerState::Responding(elems, idx) => {
9171.                 forall |i:nat| idx <= i < elems.len() && elems[i as int].is_some()
9172.                    ==> (#[trigger] self.slots[i]).is_InProgress() && (#[trigger] self.slots[i]).get_InProgress_0() == elems[i as int].unwrap()
9173.             },
9174.         }
9175.     }
9176. 
9177. 
9178. 
9179. 
9180.     ////////////////////////////////////////////////////////////////////////////////////////////
9181.     // Initialization
9182.     ////////////////////////////////////////////////////////////////////////////////////////////
9183. 
9184. 
9185.     init!{
9186.         initialize(num_threads: nat) {
9187.             init num_threads = num_threads;
9188. 
9189.             init clients = Map::new(Set::range(0, num_threads), |i| ClientState::Idle);
9190.             init slots = Map::new(Set::range(0, num_threads), |i| SlotState::Empty);
9191. 
9192.             init combiner = CombinerState::Collecting(Seq::empty());
9193.         }
9194.     }
9195. 
9196. 
9197.     ////////////////////////////////////////////////////////////////////////////////////////////
9198.     // Combiner Collection of Requests
9199.     ////////////////////////////////////////////////////////////////////////////////////////////
9200. 
9201. 
9202.     /// the combiner collects no request from the client
9203.     transition!{
9204.         combiner_collect_empty() {
9205.             require(pre.combiner.is_Collecting());
9206. 
9207.             let tid = pre.combiner.get_Collecting_0().len();
9208. 
9209.             have slots >= [ tid => let (SlotState::Empty { .. } | SlotState::Response { .. }) ];
9210. 
9211.             update combiner = CombinerState::Collecting(pre.combiner.get_Collecting_0().push(Option::None));
9212.         }
9213.     }
9214. 
9215. 
9216.     /// the combiner collects a request from the client
9217.     transition!{
9218.         combiner_collect_request() {
9219.             require(pre.combiner.is_Collecting());
9220. 
9221.             let tid = pre.combiner.get_Collecting_0().len();
9222. 
9223.             remove slots -= [ tid => let SlotState::Request(rid) ];
9224.             add    slots += [ tid => SlotState::InProgress(rid) ];
9225. 
9226.             update combiner = CombinerState::Collecting(pre.combiner.get_Collecting_0().push(Option::Some(rid)));
9227.         }
9228.     }
9229. 
9230. 
9231.     /// Safety Condition: the slot state is not in progress when collecting
9232.     property!{
9233.         pre_combiner_collect_request() {
9234.             require(pre.combiner.is_Collecting());
9235.             let idx = pre.combiner.get_Collecting_0().len();
9236.             require(idx < pre.num_threads);
9237.             have slots >= [ idx => let slot_state ];
9238. 
9239.             assert(!slot_state.is_InProgress());
9240.         }
9241.     }
9242. 
9243.     ////////////////////////////////////////////////////////////////////////////////////////////
9244.     // Combiner Responding to Requests
9245.     ////////////////////////////////////////////////////////////////////////////////////////////
9246. 
9247. 
9248.     /// combiner starts responding to requests
9249.     transition!{
9250.         combiner_responding_start() {
9251.             require(pre.combiner.is_Collecting());
9252.             require(pre.combiner.get_Collecting_0().len() == pre.num_threads);
9253. 
9254.             update combiner = CombinerState::Responding(pre.combiner.get_Collecting_0(), 0);
9255.         }
9256.     }
9257. 
9258.     /// combiner responds to an empty request
9259.     transition!{
9260.         combiner_responding_empty() {
9261.             require(pre.combiner.is_Responding());
9262.             let tid = pre.combiner.get_Responding_1();
9263. 
9264.             require(tid < pre.num_threads);
9265.             require(pre.combiner.req_is_none(tid));
9266. 
9267.             update combiner = CombinerState::Responding(pre.combiner.get_Responding_0(), tid + 1);
9268.         }
9269.     }
9270. 
9271.     /// combiner responds to a request
9272.     transition!{
9273.         combiner_responding_result() {
9274.             require(pre.combiner.is_Responding());
9275. 
9276.             let tid = pre.combiner.get_Responding_1();
9277. 
9278.             require(tid < pre.num_threads);
9279.             require(!pre.combiner.req_is_none(tid));
9280. 
9281.             update combiner = CombinerState::Responding(pre.combiner.get_Responding_0(), tid + 1);
9282.             remove slots -= [ tid => let r ];
9283.             assert let SlotState::InProgress(rid) = r;
9284.             assert pre.combiner.get_Responding_0()[tid as int].unwrap() == rid;
9285.             add    slots += [ tid => SlotState::Response(rid) ];
9286.         }
9287.     }
9288. 
9289.     /// combiner is done responding to requests
9290.     transition!{
9291.         combiner_responding_done() {
9292.             require(pre.combiner.is_Responding());
9293.             require(pre.combiner.get_Responding_1() == pre.num_threads);
9294. 
9295.             update combiner = CombinerState::Collecting(Seq::empty());
9296.         }
9297.     }
9298. 
9299. 
9300.     ////////////////////////////////////////////////////////////////////////////////////////////
9301.     // Sending
9302.     ////////////////////////////////////////////////////////////////////////////////////////////
9303. 
9304. 
9305.     /// Safety Condition: the slot state is not in progress when collecting
9306.     property!{
9307.         pre_send_request(tid: ThreadId) {
9308. 
9309.             have clients >= [ tid => let ClientState::Idle ];
9310.             have slots   >= [ tid => let slot_state ];
9311. 
9312.             assert(slot_state.is_Empty());
9313.         }
9314.     }
9315. 
9316.     transition!{
9317.         send_request(tid: ThreadId, rid: ReqId) {
9318.             remove clients -= [ tid => let ClientState::Idle ];
9319.             add    clients += [ tid => ClientState::Waiting(rid) ];
9320. 
9321.             remove slots -= [ tid => let SlotState::Empty ];
9322.             add    slots += [ tid => SlotState::Request(rid) ];
9323.         }
9324.     }
9325. 
9326.     /// Safety Condition: the slot state is not in progress when collecting
9327.     property!{
9328.         pre_recv_response(tid: ThreadId) {
9329. 
9330.             have clients >= [ tid => let ClientState::Waiting(rid) ];
9331.             have slots   >= [ tid => let slot_state ];
9332. 
9333.             assert(!slot_state.is_Empty());
9334.             assert(slot_state.get_ReqId() == rid);
9335.         }
9336.     }
9337. 
9338.     transition!{
9339.         recv_response(tid: ThreadId, rid: ReqId) {
9340.             remove clients -= [ tid => ClientState::Waiting(rid) ];
9341.             add    clients += [ tid => ClientState::Idle ];
9342. 
9343.             remove slots -= [ tid => SlotState::Response(rid) ];
9344.             add    slots += [ tid => SlotState::Empty ];
9345.         }
9346.     }
9347. 
9348. 
9349.     ////////////////////////////////////////////////////////////////////////////////////////////
9350.     // Proofs
9351.     ////////////////////////////////////////////////////////////////////////////////////////////
9352. 
9353. 
9354.     #[inductive(initialize)]
9355.     fn initialize_inductive(post: Self, num_threads: nat) { }
9356. 
9357.     #[inductive(combiner_collect_empty)]
9358.     fn combiner_collect_empty_inductive(pre: Self, post: Self) { }
9359. 
9360.     #[inductive(combiner_collect_request)]
9361.     fn combiner_collect_request_inductive(pre: Self, post: Self) {
9362.         match post.combiner {
9363.             CombinerState::Collecting(elems) => {
9364.                 let idx = pre.combiner.get_Collecting_0().len();
9365.                 assert(forall |i: nat| 0 <= i < idx
9366.                     ==> Self::slot_in_progress(post.slots, i) == Self::slot_in_progress(pre.slots, i));
9367.             },
9368.             _ => {}
9369.         }
9370.     }
9371. 
9372.     #[inductive(combiner_responding_start)]
9373.     fn combiner_responding_start_inductive(pre: Self, post: Self) { }
9374. 
